        public STFieldFormatGroupsInfo GetFieldFormatGroupByTableNameAndColumnName(String tableName, String columnName)
        {
            var list = SystemMemCache.GetFieldFormats(tableName);
            var field = list.Where(f => f.STFieldFormatColumnName == columnName).FirstOrDefault();
            if (field != null)
                return SystemMemCache.FieldFormatGroups.Where(f => f.STFieldFormatGroupID == field.STFieldFormatGroupID).FirstOrDefault();
