        /// <summary>
        /// Get format groups of all table columns of a module
        /// </summary>
        /// <param name="moduleID">Module ID</param>
        /// <returns>List of format groups</returns>
        public List<STFieldFormatGroupsInfo> GetFormatGroupsByModuleID(int moduleID)
        {
            List<STFieldFormatGroupsInfo> result = new List<STFieldFormatGroupsInfo>();
            DataSet ds = dal.GetDataSet("STFieldFormatGroups_GetFormatGroupsByModuleID", moduleID);
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    STFieldFormatGroupsInfo objFieldFormatGroupsInfo = (STFieldFormatGroupsInfo)GetObjectFromDataRow(row);
                    result.Add(objFieldFormatGroupsInfo);
                }
            }
            return result;
        }

        public List<STFieldFormatGroupsInfo> GetAll()
        {
            return GetListBusinessObjects<STFieldFormatGroupsInfo>(GetAllObjects());
        }
